import{_ as l,a0 as p,w as s,s as i,I as a,x as e,a1 as o,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"促使項目團隊作出改變的五步計劃 | LCTT x X-CMD","titleTemplate":false,"description":"促使項目團隊作出改變的五步計劃 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"促使項目團隊作出改變的五步計劃 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"促使項目團隊作出改變的五步計劃 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170126 A 5-step plan to encourage your team to make changes on your project","title":"促使項目團隊作出改變的五步計劃","tag":"201710","desc":""},"relativePath":"201710/20170126 A 5-step plan to encourage your team to make changes on your project.md","filePath":"[post].md"}'),d={name:"201710/20170126 A 5-step plan to encourage your team to make changes on your project.md"};function m(f,t,g,T,h,C){const n=p("Link");return s(),i("div",null,[t[19]||(t[19]=a("h1",{id:"促使項目團隊作出改變的五步計劃",tabindex:"-1"},[e("促使項目團隊作出改變的五步計劃 "),a("a",{class:"header-anchor",href:"#促使項目團隊作出改變的五步計劃","aria-label":"Permalink to “促使項目團隊作出改變的五步計劃”"},"​")],-1)),t[20]||(t[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BIZ_Maze2.png?itok=egeRn990",alt:"促使項目團隊作出改變的五步計劃",title:"五步的計劃促使項目團隊作出改變"})],-1)),t[21]||(t[21]=a("p",null,"目的是任何團隊組建的首要之事。如果一個人足以實現那個目的，那麼就沒有必要組成團隊。而且如果沒有重要目標，你根本不需要一個團隊。但只要任務需要的專業知識比一個人所擁有的更多，我們就會遇到集體參與的問題——如果處理不當，會使你脱離正軌。",-1)),t[22]||(t[22]=a("p",null,"想像一羣人困在洞穴中。沒有一個人具備如何出去的全部知識，所以每個人要協作，心路常開，在想要做的事情上盡力配合。當（且僅當）組建了適當的工作團隊之後，才能為實現團隊的共同目標創造出合適的環境。",-1)),t[23]||(t[23]=a("p",null,"但確實有人覺得待在洞穴中很舒適而且只想待在那裏。在組織里，領導者們如何掌控那些實際上牴觸改善、待在洞穴中覺得舒適的人？同時該如何找到擁有共同目標但是不在自己組織的人？",-1)),a("p",null,[t[1]||(t[1]=e("我從事指導國際銷售培訓，剛開始甚至很少有人認為我的工作有價值。所以，我想出一套使他們信服的戰術。那個戰術非常成功以至於我決定深入研究它並與各位",-1)),o(n,{href:"http://www.slideshare.net/RonMcFarland1/creating-change-58994683"},{default:r(()=>[...t[0]||(t[0]=[e("分享",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[24]||(t[24]=a("h3",{id:"獲得支持",tabindex:"-1"},[e("獲得支持 "),a("a",{class:"header-anchor",href:"#獲得支持","aria-label":"Permalink to “獲得支持”"},"​")],-1)),t[25]||(t[25]=a("p",null,"為了建立公司強大的企業文化，有人會反對改變，並且從幕後打壓任何改變的提議。他們希望每個人都待在那個舒適的洞穴裏。例如，當我第一次接觸到海外銷售培訓，我受到了一些關鍵人物的嚴厲阻撓。他們迫使其他人相信某個東京人做不了銷售培訓——只要基本的產品培訓就行了。",-1)),a("p",null,[t[4]||(t[4]=e("儘管我最終解決了這個問題，但我那時候真的不知道該怎麼辦。所以，我開始研究顧問們在改變公司裏抗拒改變的人的想法這個問題上該如何給出建議。從學者 ",-1)),o(n,{href:"http://www.laurencehaughton.com/"},{default:r(()=>[...t[3]||(t[3]=[e("Laurence Haughton",-1)])]),_:1}),t[5]||(t[5]=e(" 的研究中，我發現一般對於改變的提議，組織中 83% 的人最開始不會支持你。大約 17% _會_從一開始就支持你，但是隻要看到一個實驗案例成功之後，他們覺得這個主意安全可行了，60% 的人會支持你。最後，有部分人會反對任何改變，無論它有多棒。",-1))]),t[26]||(t[26]=u('<p>我研究的步驟：</p><ul><li>從試驗項目開始</li><li>開導洞穴人</li><li>快速跟進</li><li>開導洞穴首領</li><li>全局展開</li></ul><h3 id="_1、-從試驗項目開始" tabindex="-1">1、 從試驗項目開始 <a class="header-anchor" href="#_1、-從試驗項目開始" aria-label="Permalink to “1、 從試驗項目開始”">​</a></h3><p>找到高價值且成功率較高的項目——而不是大的、成本高的、週期長的、全局的行動。然後，找到能看到項目價值、理解它的價值並能為之奮鬥的關鍵人物。這些人不應該只是“老好人”或者“朋友”；他們必須相信項目的目標而且擁有推進項目的能力或經驗。不要急於求成。只要足夠支持你研究並保持進度即可。</p><p>個人而言，我在新加坡的一個小型車輛代理商那裏舉辦了自己的第一場銷售研討會。雖然並不是特別成功，但足以讓人們開始討論銷售訓練會達到怎樣的效果。那時候的我困在洞穴裏（那是一份我不想做的工作）。這個試驗銷售訓練是我走出困境的藍圖。</p><h3 id="_2、-開導洞穴人" tabindex="-1">2、 開導洞穴人 <a class="header-anchor" href="#_2、-開導洞穴人" aria-label="Permalink to “2、 開導洞穴人”">​</a></h3><p>洞穴（CAVE）實際上是我從 Laurence Haughton 那裏聽來的縮略詞。它代表着 Citizens Against Virtually Everything。（LCTT 譯註，此處一語雙關前文提及的洞穴。）</p><p>你得辨別這些人，因為他們會暗地裏阻撓項目的進展，特別是早期脆弱的時候。他們容易黑化：總是消極。他們頻繁使用“但是”、“如果”和“為什麼”，只是想推脱你。他們詢問輕易不可得的細節信息。他們花費過多的時間在問題上，而不是尋找解決方案。他們認為每個失敗都是一個趨勢。他們總是對人而不是對事。他們作出反對建議的陳述卻又不能簡單確認。</p><p>避開洞穴人；不要讓他們太早加入項目的討論。他們固守成見，因為他們看不到改變所具有的價值。他們安居於洞穴，所以試着讓他們去做些其他事。你應該找出我上面提到那 17% 的人羣中的關鍵人物，那些想要改變的人，並且跟他們開一個非常隱秘的準備會。</p><p>我在五十鈴汽車（股東之一是通用汽車公司）的時候，銷售訓練項目開始於一個銷往世界上其他小國家的合資分銷商，主要是非洲、南亞、拉丁美洲和中東。我的個人團隊由通用汽車公司雪佛蘭的人、五十鈴產品經理和分公司的銷售計劃員工組成。隔絕其他任何人於這個圈子之外。</p><h3 id="_3、-快速跟進" tabindex="-1">3、 快速跟進 <a class="header-anchor" href="#_3、-快速跟進" aria-label="Permalink to “3、 快速跟進”">​</a></h3><p>洞穴人總是慢吞吞的，那麼你就迅速行動起來。如果你在他們參與之前就有了小成就的經歷，他們對你團隊產生消極影響的能力將大大減弱——你要在他們提出之前就解決他們必然反對的問題。再一次，選擇一個成功率高的試驗項目，很快能出結果的。然後宣傳成功，就像廣告上的加粗標題。</p><p>當我在新加坡研討會上所言開始流傳時，其他地區開始意識到銷售訓練的好處。僅在新加坡研討會之後，我就被派到馬來西亞開展了四次以上。</p><h3 id="_4、-開導洞穴首領" tabindex="-1">4、 開導洞穴首領 <a class="header-anchor" href="#_4、-開導洞穴首領" aria-label="Permalink to “4、 開導洞穴首領”">​</a></h3><p>只要你取得了第一個小項目的成功，就針對能影響洞穴首領的關鍵人物推薦項目。讓團隊繼續該項目以告訴關鍵人物成功的經歷。一線人員甚至顧客也能提供有力的證明。 洞穴管理者往往只着眼於銷量和收益，那麼就宣揚項目在降低開支、減少浪費和增加銷量方面的價值。</p><p>自新加坡的第一次研討會及之後，我向直接掌握了五十鈴銷售渠道的前線銷售部門員工和通用汽車真正想看到進展的人極力宣傳他們的成功。當他們接受了之後，他們會向上級提出培訓請求並讓其看到分公司銷量的提升。</p><h3 id="_5、-全局展開" tabindex="-1">5、 全局展開 <a class="header-anchor" href="#_5、-全局展開" aria-label="Permalink to “5、 全局展開”">​</a></h3><p>一旦一把手站在了自己這邊，立馬向整個組織宣告成功的試驗項目。討論項目的擴展。</p><p>用上面的方法，在 21 年的職業生涯中，我在世界各地超過 60 個國家舉辦了研討會。我確實走出了洞穴——並且真的看到了廣闊的世界。</p><p>（題圖：opensource.com）</p><hr><p>作者簡介：</p><p>Ron McFarland - Ron McFarland 已在日本工作 40 年，從事國際銷售、銷售管理和在世界範圍內擴展銷售業務 30 載有餘。他曾去過或就職於 80 多個國家。在過去的 14 年裏， Ron 為總部位於東京的日本硬件切割廠在美國和歐洲各地建立分銷商。</p><hr>',24)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://opensource.com/open-organization/17/1/escape-the-cave"},{default:r(()=>[...t[6]||(t[6]=[e("https://opensource.com/open-organization/17/1/escape-the-cave",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),o(n,{href:"https://opensource.com/users/ron-mcfarland"},{default:r(()=>[...t[8]||(t[8]=[e("Ron McFarland",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(n,{href:"https://github.com/XYenChi"},{default:r(()=>[...t[9]||(t[9]=[e("XYenChi",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const y=l(d,[["render",m]]);e